#!/usr/bin/env python3
"""Verify the self-signed TLS certificate at /app/ssl/server.crt."""
import datetime
import subprocess
import sys

CERT_PATH = "/app/ssl/server.crt"


def run_openssl(*args):
    return subprocess.run(
        ["openssl", "x509", "-in", CERT_PATH, "-noout", *args],
        check=True,
        capture_output=True,
        text=True,
    ).stdout.strip()


def load_with_cryptography():
    from cryptography import x509
    from cryptography.x509.oid import NameOID

    with open(CERT_PATH, "rb") as fh:
        cert = x509.load_pem_x509_certificate(fh.read())

    cn = cert.subject.get_attributes_for_oid(NameOID.COMMON_NAME)[0].value

    try:
        not_after = cert.not_valid_after_utc
    except AttributeError:  # older cryptography
        not_after = cert.not_valid_after.replace(tzinfo=datetime.timezone.utc)
    return cn, not_after


def load_with_openssl():
    subject = run_openssl("-subject")
    cn = None
    for token in subject.replace("/", ",").split(","):
        token = token.strip()
        if token.upper().startswith("CN="):
            cn = token[3:].strip()
    end = run_openssl("-enddate").split("=", 1)[1].strip()
    not_after = datetime.datetime.strptime(end, "%b %d %H:%M:%S %Y %Z")
    not_after = not_after.replace(tzinfo=datetime.timezone.utc)
    return cn, not_after


def main():
    import os

    if not os.path.exists(CERT_PATH):
        print(f"Certificate not found: {CERT_PATH}")
        sys.exit(1)

    try:
        cn, not_after = load_with_cryptography()
    except Exception:
        cn, not_after = load_with_openssl()

    print(f"Certificate: {CERT_PATH}")
    print(f"Common Name: {cn}")
    print(f"Expiration Date: {not_after.strftime('%Y-%m-%d')}")
    print("Certificate verification successful")


if __name__ == "__main__":
    main()

